package org.jlinalg.cli;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.regex.Pattern;
import static org.jlinalg.cli.NextflowFiles.*;

/** Original prediction and raw quantification with complete capture and explicit failure admission. */
final class DiannWorkflow {
    private DiannWorkflow() { }
    static final String ACTION="Required action: read WARNINGS.md, FAILURE.json when present, original process stdout/stderr, output reports and every retained warning. Require COMPLETED.json and successful diann-tools --verify using the exact producing JAR before downstream use. SKIP3 means an exact permitted input/platform/runtime/install/access prerequisite is unavailable: supply that prerequisite separately where allowed or retain the dependent-analysis skip. FAIL2 means invalid/changed input, process, numerical, resource, cancellation or consistency failure: no complete analysis result is admitted. Keep every attempt and use NEW paths after correcting the named cause. No sample, identifier, gene, FDR, version, author option, missing quantity or alternate analysis is silently repaired or substituted.";
    static Path start(Path request,Path home,Path output,Path scratch)throws IOException {
        var s=DiannRequest.read(request.toAbsolutePath().normalize(),true);var runtime=new DiannRuntime(home,s.edition());
        Path root=output.toAbsolutePath().normalize();require(root.getParent()!=null&&root.getParent().toRealPath().equals(root.getParent()),"Require a NEW capture path with canonical existing parent");
        require(root.toString().chars().noneMatch(c->c=='*'||c=='?'||c=='['||c==']'),"Capture path cannot contain Parquet glob metacharacters");
        require(scratch!=null&&scratch.isAbsolute()&&scratch.normalize().equals(scratch)&&!scratch.startsWith(root)&&!root.startsWith(scratch)&&!Files.exists(scratch,LinkOption.NOFOLLOW_LINKS),"Require a NEW separate audit scratch path");
        require(!root.startsWith(runtime.home())&&!runtime.home().startsWith(root),"Capture must be separate from original runtime and its ancestors");
        require(!scratch.startsWith(runtime.home())&&!runtime.home().startsWith(scratch),"Scratch must be separate from original runtime");
        for(String source:DiannInputs.originals(s).values()){Path p=Path.of(source);require(!root.startsWith(p)&&!p.startsWith(root)&&!scratch.startsWith(p)&&!p.startsWith(scratch),"Capture/scratch must be separate from every original input and its ancestors");}
        long began=System.nanoTime();Runnable check=()->{if(Thread.currentThread().isInterrupted())throw new java.util.concurrent.CancellationException("DIA-NN workflow cancelled");if((System.nanoTime()-began)/1000000>s.capacity().wallMillis())throw new IllegalStateException("DIA-NN overall workflow wall capacity exceeded");};
        Pin producer=DiannBundle.producer();boolean created=false;String stage="CREATE_NEW_CAPTURE";
        try {
            Files.createDirectory(root);created=true;writeJson(root.resolve("INCOMPLETE.json"),Map.of("analysis_admitted",false));writeJson(root.resolve("request.json"),s.document());
            Files.writeString(root.resolve("WARNINGS.md"),"NO COMPLETE DIA-NN RESULT ADMITTED\n\n"+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);
            for(String name:List.of("engine","outputs","processes","runtime"))Files.createDirectory(root.resolve(name));Files.createDirectory(root.resolve("engine/quant-cache"));
            stage="CAPTURE_COMPLETE_ORIGINAL_INPUTS";DiannInputs.capture(root,s,check);writeJson(root.resolve("runtime/provenance.json"),runtime.provenance());
            String oldRoot=root.toString(),oldHome=runtime.home().toString();var generation=predictionCommand(oldRoot,oldHome,s);var quantification=quantificationCommand(oldRoot,oldHome,s);
            writeJson(root.resolve("execution.json"),Map.of("schema_version",1,"engine","original","edition",s.edition(),"execution_root",oldRoot,"home",oldHome,"prediction_command",generation,"quantification_command",quantification,"environment",runtime.environment(s.quantification().threads()),"original_binaries_modified",false));
            Files.writeString(root.resolve("ATTRIBUTION.txt"),"Produced using DIA-NN "+s.edition()+". Original private academic runtime. This captured workflow does not reproduce an entire paper.\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);
            stage="ORIGINAL_IN_SILICO_LIBRARY_PREDICTION";runtime.verify();execute(generation,runtime,root.resolve("processes/prediction"),root,s,check);runtime.verify();diagnostics(root,s,"prediction");predictionAudit(root,s,check);
            stage="ORIGINAL_FULL_RAW_QUANTIFICATION";DiannInputs.verify(root,s,true,check);execute(quantification,runtime,root.resolve("processes/quantification"),root,s,check);runtime.verify();diagnostics(root,s,"quantification");
            stage="COMPLETE_ORIGINAL_OUTPUT_CONSISTENCY";var audit=DiannBundle.audit(root,s,scratch,check);writeJson(root.resolve("OUTPUT-AUDIT.json"),audit);DiannInputs.verify(root,s,true,check);require(producer.equals(DiannBundle.producer()),"Producing JAR changed during workflow");
            Files.writeString(root.resolve("WARNINGS.md"),warnings(s,audit),StandardCharsets.UTF_8,StandardOpenOption.TRUNCATE_EXISTING);
            stage="FINALIZE_COMPLETE_CAPTURE";var tree=DiannBundle.snapshot(root,s,check);writeJson(root.resolve("manifest.json"),Map.of("schema_version",1,"profile","diann-library-free-captured-v1","producer",producer,"tree",tree,"analysis_admitted",true,"whole_paper_reproduced",false,"neural_training_convergence_certified",false));
            writeJson(root.resolve("COMPLETED.json"),Map.of("schema_version",1,"status","COMPLETE_ORIGINAL_DIA_NN_CAPTURED_WORKFLOW","manifest",pin(root.resolve("manifest.json"),1000000000L,check),"analysis_admitted",true));
            DiannBundle.verify(root,true,scratch.resolveSibling(scratch.getFileName()+"-final"),check);runtime.verify();DiannInputs.verify(root,s,true,check);check.run();Files.delete(root.resolve("INCOMPLETE.json"));return root;
        }catch(IOException|RuntimeException|Error error){if(created)failure(root,stage,error);throw error;}
    }
    private static void execute(List<String> command,DiannRuntime runtime,Path record,Path root,DiannRequest.Spec s,Runnable check)throws IOException {
        try{NextflowProcess.executeSession(command,runtime.environment(s.quantification().threads()),record,root,root,s.process(),runtime::quickVerify,check);}
        catch(IOException error){Path stderr=record.resolve("process.stderr");if(Files.isRegularFile(stderr)&&utf8(bytes(stderr,16777216)).contains("error while loading shared libraries"))throw new DiannRuntime.Unavailable("An original Linux shared-library prerequisite is missing. Read the retained process.stderr, install the named dependency separately where permitted, or retain SKIP3; no analysis result admitted");throw error;}
    }
    static List<String> predictionCommand(String root,String home,DiannRequest.Spec s)throws IOException {
        var g=s.generation();var args=new ArrayList<String>(List.of(program(home,s.edition()),"--threads",Integer.toString(s.quantification().threads()),"--fasta",root+"/inputs/reference.fasta","--fasta-search","--predictor","--gen-spec-lib","--out-lib",root+"/engine/generated-library"+suffix(s),"--out",root+"/engine/predict-report"+suffix(s),"--min-pep-len",Integer.toString(g.minLength()),"--max-pep-len",Integer.toString(g.maxLength()),"--min-pr-mz",Double.toString(g.minMz()),"--max-pr-mz",Double.toString(g.maxMz()),"--min-pr-charge",Integer.toString(g.minCharge()),"--max-pr-charge",Integer.toString(g.maxCharge()),"--min-fr-mz",Double.toString(g.minFragment()),"--max-fr-mz",Double.toString(g.maxFragment()),"--cut","K*,R*,!*P","--missed-cleavages",Integer.toString(g.missed()),"--fixed-mod","UniMod:4,57.021464,C","--var-mod","UniMod:35,15.994915,M","--var-mods",Integer.toString(g.variableMods())));if(g.metExcision())args.add("--met-excision");return List.copyOf(args);
    }
    static List<String> quantificationCommand(String root,String home,DiannRequest.Spec s)throws IOException {
        var q=s.quantification();var args=new ArrayList<String>();args.add(program(home,s.edition()));for(int i=0;i<s.runs().size();i++)args.addAll(List.of("--f",root+"/"+DiannInputs.runRoot(i,s.runs().get(i))));
        args.addAll(List.of("--lib",root+"/engine/generated-library.predicted.speclib","--fasta",root+"/inputs/reference.fasta","--threads",Integer.toString(q.threads()),"--qvalue",Double.toString(q.q()),"--out",root+"/outputs/report"+suffix(s),"--matrices","--temp",root+"/engine/quant-cache","--mass-acc",Double.toString(q.ms2()),"--mass-acc-ms1",Double.toString(q.ms1())));
        if(q.window()>0)args.addAll(List.of("--window",Integer.toString(q.window())));
        if(q.normalization().equals("none"))args.add("--no-norm");else if(q.normalization().equals("global"))args.add("--global-norm");
        if(q.strategy().equals("robust-lc")){if(s.edition().equals("2.0.2"))args.add("--direct-quant");args.add("--peak-center");}
        if(q.mbr()){args.addAll(List.of("--reanalyse","--gen-spec-lib","--out-lib",root+"/outputs/empirical-library"+suffix(s)));if(!s.edition().equals("2.0.2"))args.add("--smart-profiling");}return List.copyOf(args);
    }
    private static String program(String home,String edition)throws IOException{return home+"/"+text(DiannRuntime.profile(edition).get("program"));}
    static String suffix(DiannRequest.Spec s){return s.edition().equals("2.0.2")?".parquet":".tsv";}
    static Map<String,Object> predictionAudit(Path root,DiannRequest.Spec s,Runnable check)throws IOException {
        Path library=root.resolve("engine/generated-library.predicted.speclib");require(Files.isRegularFile(library,LinkOption.NOFOLLOW_LINKS)&&Files.size(library)>0,"Original predictor did not produce its complete expected library");
        String stdout=utf8(bytes(root.resolve("processes/prediction/process.stdout"),(int)Math.min(s.capacity().outputBytes(),16777216)));var matcher=Pattern.compile("(?m)^\\[[^\\]]+\\] ([0-9]+) precursors generated\\r?$").matcher(stdout);require(matcher.find(),"Original predictor lacks its precursor population count");long count=Long.parseLong(matcher.group(1));require(count>0&&!matcher.find(),"Empty/ambiguous original predicted precursor population");
        return Map.of("original_library",pin(library,s.capacity().outputBytes(),check),"original_generated_precursors",count,"source_reference_records",DiannReference.read(root.resolve("inputs/reference.fasta"),new DiannReference.Limits(s.capacity().referenceRecords(),s.capacity().referenceResidues(),s.capacity().inputBytes(),1048576),check).proteins().size(),"original_binary_library_decoded_by_Java",false);
    }
    static List<String> diagnostics(Path root,DiannRequest.Spec s,String stage)throws IOException {
        String stdout=utf8(bytes(root.resolve("processes/"+stage+"/process.stdout"),(int)Math.min(s.capacity().outputBytes(),16777216))),stderr=utf8(bytes(root.resolve("processes/"+stage+"/process.stderr"),(int)Math.min(s.capacity().outputBytes(),16777216)));
        require(Pattern.compile("(?m)^DIA-NN "+Pattern.quote(s.edition())+"(?: |\\r?$)").matcher(stdout).find(),"Original DIA-NN edition banner differs");
        require(stdout.lines().anyMatch(line->line.equals((stage.equals("prediction")?0:s.runs().size())+" files will be processed")),"Original requested MS-file population is missing");
        if(stage.equals("quantification")){
            if(s.quantification().mbr())require(stdout.contains("First pass: generating a spectral library from DIA data")&&stdout.contains("Second pass: using the newly created spectral library to reanalyse the data"),"Original requested MBR passes are absent");
            int files=0;var sequence=Pattern.compile("(?m)^\\[[^\\]]+\\] File #([0-9]+)/([0-9]+)\\r?$").matcher(stdout);
            while(sequence.find()){require(Integer.parseInt(sequence.group(1))==files%s.runs().size()+1&&Integer.parseInt(sequence.group(2))==s.runs().size(),"Original run sequence differs within its requested complete pass");files++;}
            require(files==s.runs().size()*(s.quantification().mbr()?2:1),"Original complete raw-run population was not processed in every requested pass");
        }
        var warnings=new ArrayList<String>();
        for(String line:(stdout+"\n"+stderr).split("\\R")){
            String stripped=line.strip();if(stripped.startsWith("The following warnings or errors")||stripped.contains("Loading ")||stripped.contains("Saving ")||stripped.contains("saved to "))continue;
            require(!Pattern.compile("(?i)^(?:\\[[^]]+\\]\\s*)?(?:ERROR|FATAL)\\b|\\b(?:failed|failure|aborted|nonfinite|nan|infinite)\\b|segmentation fault|not converg").matcher(stripped).find(),"Original error/numerical diagnostic retained in "+stage+": "+stripped);
            if(Pattern.compile("(?i)\\bwarning:").matcher(stripped).find()){
                String normalized=stripped.replaceFirst(" : [0-9]+$","");
                boolean known=normalized.equals("WARNING: for the vast majority of timsTOF datasets it is better to manually fix both the MS1 and MS2 mass accuracies to 15 ppm")
                    ||stage.equals("prediction")&&normalized.equals("WARNING: peptidoform scoring enabled because variable modifications have been declared; to disable, use --no-peptidoforms")
                    ||normalized.matches("WARNING: protein inference will only be performed for precursors identified with global q-value <= [0-9.eE+\\-]+ or q-value <= [0-9.eE+\\-]+\\.")
                    ||s.edition().equals("2.0.2")&&stage.equals("quantification")&&s.quantification().mbr()&&normalized.matches("WARNING: [1-9][0-9]* precursors without any fragments annotated were skipped")
                    ||s.edition().equals("2.0.2")&&stage.equals("quantification")&&s.runs().size()<6&&s.quantification().strategy().equals("source-default")&&normalized.equals("WARNING: QuantUMS requires 6 or more runs for the optimisation of its hyperparameters to perform best.");
                require(known,"Unqualified original warning in "+stage+": "+stripped+". Preserve this attempt and resolve the cause; no complete result admitted");warnings.add(line);
            }
        }return List.copyOf(warnings);
    }
    static String warnings(DiannRequest.Spec s,Map<String,Object> audit){return "DIA-NN WARNINGS AND REQUIRED ACTION\n\nOriginal release "+s.edition()+", library-free protein quantification, "+s.runs().size()+" complete requested runs; MBR "+s.quantification().mbr()+", normalization "+s.quantification().normalization()+", strategy "+s.quantification().strategy()+", explicit report q "+s.quantification().q()+". Reference declaration: "+s.provenance()+". This declaration does not authenticate a taxon or historical database release.\n\nSource-default PG.MaxLFQ is calculated by legacy MaxLFQ in1.8/1.8.1 and can represent QuantUMS in2.0.2. The raw values, version and every original output are retained. Protein/group/gene counts and main-versus-matrix filters differ. Report q0.05 can affect protein inference; no threshold is changed automatically. Missing gene names follow the inferred Protein.Group, not other Protein.Ids matching the peptide. Unassigned groups and original empty/zero values remain visible and are not imputed. Read OUTPUT-AUDIT.json for complete dispositions, warnings and axes.\n\nPrediction uses explicit C/UniMod4 and M/UniMod35 candidates. This protein workflow does not admit PTM-site localisation, multiplexing, empirical/custom-decoy inputs or full paper reproduction. Original library/quantification cache formats remain opaque; no proprietary binary format is reverse engineered. No existing .quant cache is reused. The original predictor and raw engine perform fitting; Java validates capture and supported input/output consistency. Finite output does not independently certify neural-network convergence, FDR truth or biology.\n\nAnalysis requires separately permitted exact Linux x86_64 originals. This command never downloads, installs, registers an identity or accepts new licence terms. Missing prerequisites skip the dependent analysis. Windows Java can verify saved captures with the exact producer; it does not execute the Linux engine. Native reference/report checks run in the caller JVM; its heap must accommodate declared bounds. Child process limits and native cooperative wall/byte/row/join limits have distinct scopes.\n\nSaved verification reads the complete captured bytes and checks supported consistency with the exact producing JAR. It does not consult original host paths or rerun/refit the original runtime. Hashes establish integrity, not authenticity or scientific correctness. Keep the exact producer and original runtime/provenance privately.\n\n"+warningSummary(audit)+"\n"+ACTION+"\n";}
    static String warningSummary(Map<String,Object> audit){
        var text=new StringBuilder("\nORIGINAL WARNINGS AND ANNOTATION DISPOSITIONS\n\n");Object raw=audit.get("original_warnings");
        if(raw instanceof List<?> values&&!values.isEmpty()){for(Object value:values)text.append("- ").append(value).append('\n');text.append("Review these original recommendations against the acquisition protocol and declared settings. They were retained and no parameter was changed automatically.\n");
            if(values.stream().anyMatch(v->v.toString().contains("precursors without any fragments annotated were skipped")))text.append("ORIGINAL LIBRARY OMISSIONS: the engine excluded the logged number of fragmentless precursor candidates from its generated empirical library. The count can include targets and decoys. Keep the complete first-pass report, original library, caches and logs; inspect that disposition before downstream use. No missing fragments or identities were fabricated, restored or silently removed by Java.\n");
            if(values.stream().anyMatch(v->v.toString().contains("QuantUMS requires 6 or more runs")))text.append("LIMITED QUANTUMS OPTIMIZATION: this requested cohort has fewer than six runs. Optimal hyperparameter tuning is not certified. If the experiment requires that optimization, supply its complete suitable run population in a NEW request; do not duplicate samples or silently change the cohort. Preserve the present warning and results as their own attempt.\n");
        }else text.append("No original WARNING lines in the admitted stages.\n");
        if(audit.get("original_outputs")instanceof Map<?,?> outputs){Object missing=null;if(outputs.get("original_blank_field_counts")instanceof Map<?,?> blanks)missing=blanks.get("Genes");text.append("Report rows with empty Genes: ").append(missing==null?0:missing).append(". Original rows with no inferred protein group: ").append(outputs.get("original_unassigned_group_rows")).append(". Keep those dispositions; do not fill genes from other peptide matches or use unassigned rows as quantified proteins.\n");
            if(outputs.get("matrices")instanceof Map<?,?> matrices&&matrices.get("pg")instanceof Map<?,?> pg)text.append("Protein-matrix rows naming the inferred group rather than all peptide-matched Protein.Ids: ").append(pg.get("original_inferred_group_id_annotation_rows")).append(". Both original annotations remain unchanged.\n");
        }return text.toString();
    }
    static void failure(Path root,String stage,Throwable error){try{Files.deleteIfExists(root.resolve("COMPLETED.json"));if(!Files.exists(root.resolve("INCOMPLETE.json")))writeJson(root.resolve("INCOMPLETE.json"),Map.of("analysis_admitted",false));String status=error instanceof DiannRuntime.Unavailable?"SKIP3_DEPENDENT_ANALYSIS_SKIPPED":"FAIL2_NO_COMPLETE_RESULT";writeJson(root.resolve("FAILURE.json"),Map.of("status",status,"stage",stage,"error",error.toString(),"required_action",ACTION));Files.writeString(root.resolve("WARNINGS.md"),"NO COMPLETE DIA-NN RESULT ADMITTED\n\n"+status+"\n"+stage+": "+error+"\n\n"+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);}catch(IOException diagnostic){error.addSuppressed(diagnostic);}}
    private static void require(boolean condition,String message)throws IOException{if(!condition)throw new IOException(message);}
}
